using System;using System.Linq;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;using UnityEditor.SceneManagement;
namespace LWS.TruckFieldGoal.Editor {
public static class FieldGoalStadiumAuthoring {
 // Reuse already-authored Union Field render geometry without loading Taxi
 // runtime, roads, crowds, colliders, listeners or modifying its saved scene.
 public static void Reuse(){var destination=SceneManager.GetActiveScene();var source=EditorSceneManager.OpenScene("Assets/LWS/TruckTaxi/Regional/Scenes/Taxi_SportsStadium.unity",OpenSceneMode.Additive);try{SceneManager.SetActiveScene(destination);var renderers=source.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<MeshRenderer>(true)).ToArray();var field=renderers.First(r=>r.name=="Playing field");Vector3 center=field.bounds.center;var rotation=Quaternion.Euler(0,90,0);var holder=new GameObject("Reused Union Field stadium render geometry").transform;int count=0;foreach(var r in renderers){if(r.name!="Grandstand tier"&&r.name!="End-zone concourse"&&r.name!="Press box")continue;var filter=r.GetComponent<MeshFilter>();if(filter==null||filter.sharedMesh==null)continue;var model=new GameObject("Union Field "+r.name);model.transform.SetParent(holder,false);model.transform.SetPositionAndRotation(rotation*((r.transform.position-center)*.85f)+new Vector3(0,0,30),rotation*r.transform.rotation);model.transform.localScale=r.transform.lossyScale*.85f;model.AddComponent<MeshFilter>().sharedMesh=filter.sharedMesh;model.AddComponent<MeshRenderer>().sharedMaterials=r.sharedMaterials;count++;}if(count<10)throw new Exception("Existing stadium render foundation incomplete");Debug.Log("FIELD_GOAL_REUSED_STADIUM_RENDERERS "+count);}finally{SceneManager.SetActiveScene(destination);EditorSceneManager.CloseScene(source,true);}}
}
}
